def allocate(total: int, weights: list[int]) -> list[int]:
    """Split `total` minor units over lines in proportion to `weights`.

    Shares are whole minor units and add up to `total` exactly (largest
    remainder method; equal remainders are served in line order).
    """
    if total < 0 or any(w < 0 for w in weights):
        raise ValueError("allocation of a negative amount")
    whole = sum(weights)
    if total == 0 or whole == 0:
        return [0] * len(weights)
    if total > whole:
        raise ValueError(f"cannot take {total} from lines worth {whole}")
    shares = []
    remainders = []
    for w in weights:
        q, r = divmod(total * w, whole)
        shares.append(q)
        remainders.append(r)
    left = total - sum(shares)
    if left:
        order = sorted((i for i in range(len(weights)) if remainders[i] > 0), key=lambda i: (-remainders[i], i))
        for i in order[:left]:
            shares[i] += 1
    return shares

